export const passwordsMatch: ValidatorFn = (group) =>
  group.get('password')?.value === group.get('confirm')?.value
    ? null : { passwordsMismatch: true };

export function uniqueEmail(api: UserApi): AsyncValidatorFn {
  return (control) => api.emailExists(control.value).pipe(
    map(exists => (exists ? { emailTaken: true } : null)),
  );
}

